<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api } from '../api'
import { usePolling } from '../usePolling'
import type { Assessment, Radar, RadarEvent } from '../types'
import { direction, number, percent, price, statusName, time } from '../format'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import Pager from '../components/Pager.vue'
const radar=ref<Radar|null>(null); const events=ref<RadarEvent[]>([]); const search=ref(''); const side=ref('all'); const candidates=ref(true); const page=ref(0)
const selected=ref<{symbol:string; assessment:Assessment; asOf:string}|null>(null)
async function loadEvents(signal?:AbortSignal) { events.value=await api<RadarEvent[]>('/api/volatility/events?limit=30',{signal}) }
const {error,refresh}=usePolling(async signal=>{const next=await api<Radar>('/api/volatility',{signal}); if(next.scanId!==radar.value?.scanId) await loadEvents(signal); radar.value=next},3000)
const rows=computed(()=>(radar.value?.observations??[]).flatMap(o=>[o.up,o.down].map(a=>({o,a}))).filter(x=>x.o.input.instrument.symbol.toLowerCase().includes(search.value.trim().toLowerCase())&&(side.value==='all'||Number(side.value)===x.a.direction)&&(!candidates.value||x.a.isCandidate)).sort((a,b)=>(b.a.score??-1)-(a.a.score??-1)))
const paged=computed(()=>rows.value.slice(page.value*30,(page.value+1)*30))
watch([search,side,candidates],()=>{page.value=0})
const regime=(n:number|null|undefined)=>n==null?'Unknown':['Normal','BroadRiskOn','BroadRiskOff','SystemicPump','SystemicCrash'][n]??'Unknown'
</script>
<template><PageIntro eyebrow="VOLATILITY RADAR" title="异动研究，不是买入指令。" description="上涨与下跌分别检测，同一行情按 Episode 持续追踪。"><span class="live-pill">{{radar?'后台检测运行中':'等待扫描'}}</span></PageIntro><p v-if="error" class="radar-notice" role="alert">{{error}} 缓存结果请核对扫描时间。</p><p class="radar-notice">深度证据可用时采用 V2；基础模型置信度上限为 60。上涨候选、Breakout 和高分描述已观测异动，不是推荐买入；模拟盘另有入场、仓位和退出规则。分数、数据完整度和风险分别判断，缺失数据不会当作 0。</p>
<template v-if="radar"><div class="stats"><StatCard label="市场状态 · 1h" :value="regime(radar.market.regime)" :foot="`有效覆盖 ${radar.market.validAssets}/${radar.market.totalAssets} · ${number(radar.market.coveragePercent)}%`"/><StatCard label="市场中位收益 · 1h" :value="percent(radar.market.medianReturn1h)" :foot="`上涨 ${radar.market.advancing} · 下跌 ${radar.market.declining}`"/><StatCard label="上涨候选 / 下跌候选" :value="`${radar.observations.filter(o=>o.up.isCandidate).length} / ${radar.observations.filter(o=>o.down.isCandidate).length}`" foot="方向观察，非入场指令"/><StatCard label="活跃 Episode" :value="radar.activeEpisodes.length" :foot="time(radar.asOf)"/></div><details class="detail"><summary>市场广度与分类依据</summary><p>{{radar.market.reason}}</p><p>1h &gt; +5%：{{radar.market.above5}}　&lt; −5%：{{radar.market.belowMinus5}}　&gt; +10%：{{radar.market.above10}}　&lt; −10%：{{radar.market.belowMinus10}}</p><p>BTC {{percent(radar.market.btcReturn1h)}} · ETH {{percent(radar.market.ethReturn1h)}}</p></details>
<div class="section-heading radar-heading"><h2>异动观察台</h2><span class="refresh-text">页面每 3 秒读取 · 检测默认每 60 秒运行</span></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索雷达合约" placeholder="搜索合约，例如 ARIA"></label><select v-model="side" aria-label="雷达方向"><option value="all">全部方向</option><option value="0">上涨</option><option value="1">下跌</option></select><label class="checkbox"><input v-model="candidates" type="checkbox">仅候选</label><span class="results">{{rows.length}} 个结果</span></div><div class="table-scroll"><table><thead><tr><th>合约</th><th>方向</th><th>分数 ↓</th><th>置信度</th><th>阶段</th><th>确认家族</th><th>数据</th><th>Episode</th><th>详情</th></tr></thead><tbody><tr v-for="{o,a} in paged" :key="`${o.input.instrument.assetId}:${a.direction}`"><td>{{o.input.instrument.symbol}}</td><td :class="a.direction===0?'positive':'negative'">{{direction(a.direction)}}</td><td>{{number(a.score,1)}}</td><td>{{a.dataConfidence}} / 100</td><td>{{a.stage}}</td><td>{{a.confirmedFamilies.join(' · ')}}</td><td>{{statusName(a.status)}}</td><td>{{o.episodeId??'—'}}</td><td><button class="text-button" @click="selected={symbol:o.input.instrument.symbol,assessment:a,asOf:radar!.asOf}">依据 →</button></td></tr><tr v-if="!rows.length"><td colspan="9" class="empty">没有符合条件的异动候选，可关闭“仅候选”查看全部结果。</td></tr></tbody></table></div><Pager v-model="page" :total="rows.length">不同策略版本的分数不能直接混同。</Pager></div>
<section v-if="selected" class="detail"><div class="section-heading"><h2>{{selected.symbol}} · {{direction(selected.assessment.direction)}} · {{selected.assessment.stage}}</h2><button class="text-button" @click="selected=null">收起 ×</button></div><p>版本 {{selected.assessment.strategyVersion}} · 选中快照 {{time(selected.asOf)}}</p><p v-for="reason in selected.assessment.reasons" :key="reason">{{reason}}</p><p>缺失证据：{{selected.assessment.missingFamilies.join(' · ')}}</p><div class="detail-grid"><div v-for="c in selected.assessment.components" :key="c.family"><span>{{c.family}} · 权重 {{c.weight}} / {{selected.assessment.components.reduce((sum,c)=>sum+c.weight,0)}}</span><strong>强度 {{number(c.strength)}} · {{c.confirmed?'已确认':'待确认'}}</strong><small>{{time(c.sourceTime,true)}}</small></div></div></section>
<div class="section-heading radar-heading"><h2>活跃行情 Episode</h2></div><div class="market-panel table-scroll"><table><thead><tr><th>合约 / 方向</th><th>阶段</th><th>状态</th><th>开始 / 最近观察</th><th>起始价 → 当前价</th><th>最高 / 最低</th><th>当前 / 最高分</th><th>数据</th></tr></thead><tbody><tr v-for="e in radar.activeEpisodes" :key="e.id"><td :title="String(e.id)">{{e.symbol}} · {{direction(e.direction)}}</td><td>{{e.stage}}</td><td>{{['Created','Active','Escalating','Overheated','Cooling','Closed'][e.state]}}</td><td>{{time(e.startTime)}} / {{time(e.lastObservedTime)}}</td><td>{{price(e.startPrice)}} → {{price(e.currentPrice)}}</td><td>{{price(e.peakPrice)}} / {{price(e.lowestPrice)}}</td><td>{{number(e.currentScore,1)}} / {{number(e.maxScore,1)}}</td><td>{{statusName(e.dataStatus)}}</td></tr><tr v-if="!radar.activeEpisodes.length"><td colspan="8" class="empty">暂无活跃 Episode。</td></tr></tbody></table></div></template>
<div class="section-heading radar-heading"><h2>已保存事件</h2><button class="text-button" @click="refresh">刷新记录</button></div><div class="market-panel table-scroll"><table><thead><tr><th>时间</th><th>合约</th><th>方向 / 事件</th><th>阶段</th><th>分数</th><th>版本</th><th>依据</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{time(e.time,true)}}</td><td>{{e.symbol}}</td><td>{{direction(e.direction)}} · {{e.kind}}</td><td>{{e.episode.stage}} {{e.episode.endReason}}</td><td>{{number(e.assessment?.score,1)}}</td><td>{{e.strategyVersion}}</td><td><button v-if="e.assessment" class="text-button" @click="selected={symbol:e.symbol,assessment:e.assessment,asOf:e.time}">查看</button></td></tr><tr v-if="!events.length"><td colspan="7" class="empty">暂无保存事件。</td></tr></tbody></table></div></template>
